reference_solution:
def nextGreaterElements(nums):
    n = len(nums)
    res = [-1] * n
    st = []
    for i in range(2 * n):
        x = nums[i % n]
        while st and nums[st[-1]] < x:
            res[st.pop()] = x
        if i < n:
            st.append(i)
    return res

brute_force_solution:
def nextGreaterElements(nums):
    n = len(nums)
    res = []
    for i in range(n):
        ans = -1
        for j in range(1, n):
            if nums[(i + j) % n] > nums[i]:
                ans = nums[(i + j) % n]
                break
        res.append(ans)
    return res

